const fs = require('fs');
const path = require('path');

const targetDir = path.join(__dirname, '../../js/data/interviewPrep');

function createModuleFile(filename, varName, category, title, description, icon, topics, questions) {
  const content = `/**
 * MAD DEV — ${title} Question Bank
 * ${questions.length} authentic placement/interview MCQs across ${topics.length} topics.
 */

(function () {
  'use strict';

  const ${varName} = {
    category: "${category}",
    title: "${title}",
    description: "${description}",
    icon: "${icon}",
    totalTopics: ${topics.length},
    topics: ${JSON.stringify(topics, null, 2)},
    questions: ${JSON.stringify(questions, null, 2)}
  };

  if (typeof window !== 'undefined') {
    window.interviewPrepData = window.interviewPrepData || {};
    window.interviewPrepData['${category}'] = ${varName};
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = ${varName};
  }
})();
`;
  fs.writeFileSync(path.join(targetDir, filename), content, 'utf8');
  console.log(`Successfully generated ${filename} (${questions.length} questions across ${topics.length} topics)`);
}

